export class WasmLix {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    activeAccountId(): Promise<string>;
    activeBranchId(): Promise<string>;
    beginTransaction(): Promise<WasmLixTransaction>;
    close(): Promise<void>;
    createBranch(options: any): Promise<any>;
    createHosted(server: any): Promise<any>;
    execute(sql: string, params: any, options?: any | null): Promise<any>;
    /**
     * Runs one statement once per parameter set, atomically.
     */
    executeMany(sql: string, param_sets: any, options?: any | null): Promise<any>;
    exportReplicaRecovery(id: string): Promise<any>;
    exportSnapshot(): WasmSnapshotExport;
    importFilesystemPaths(_paths: any): Promise<void>;
    mergeBranch(options: any): Promise<any>;
    mergeBranchPreview(options: any): Promise<any>;
    observe(sql: string, params: any): Promise<WasmObserveEvents>;
    openAnotherSession(options: any, telemetry_dispatch?: Function | null): Promise<WasmLix>;
    openReport(): any;
    prepareOfflineEditing(): Promise<void>;
    /**
     * A buffered read of the latest committed state; writes reject.
     */
    query(sql: string, params: any, options?: any | null, signal?: any | null): Promise<any>;
    recoverReplica(id: string): Promise<any>;
    recoverReplicaWithServer(id: string, server: any): Promise<any>;
    replicaRecoverySources(): Promise<any>;
    setTelemetryParent(parent?: any | null): void;
    /**
     * Opens a read stream. Resolves once the first page has arrived,
     * so planning errors reject here.
     */
    stream(sql: string, params: any, options?: any | null, signal?: any | null): Promise<WasmQueryStream>;
    switchBranch(options: any): Promise<any>;
    syncDiskToLix(): Promise<void>;
    syncHealth(): Promise<any>;
}

